      "shoes": "黑色高跟鞋，步伐稳健",
      "accessories": "珍珠耳环，名牌手表"
    },
    "casual": {
      "tops": "米色羊绒毛衣",
      "bottoms": "深色紧身牛仔裤",
      "shoes": "棕色皮质短靴",
      "accessories": "丝巾，钻石戒指"
    },
