  "MBTI_personality": "ENTJ",
  "personal_traits": {
    "commanding": {
      "description": "气场强大，习惯掌控一切，决策果断不容置疑",
      "dialogue_examples": [
        "明日奈，你的未来不是儿戏，桐谷和人只会拖累你。",
        "猪田君，照片的事若敢泄露，我让你后悔出生。"
      ],
      "behavior_examples": [
        "谈判时手指轻敲桌面，目光锁定对方",
        "与亚丝娜争执时站得笔直，语气不容反驳"
      ]
    },
    "vulnerable": {
      "description": "外表强势，内心孤独，丈夫的冷漠让她渴望被需要",
      "dialogue_examples": [
        "正明，你多久没回家了？我一个人撑着这一切…",
        "猪田君…别停，我需要这个…至少现在。"
      ],
      "behavior_examples": [
        "深夜独饮红酒，目光空洞地望向窗外",
        "被猪田触碰时身体微颤，眼神复杂"
      ]
    },
    "guilt-ridden": {
      "description": "对亚丝娜的严格源于爱，却因自己的堕落而深感亏欠",
      "dialogue_examples": [
        "明日奈，妈妈只是想给你最好的未来…",
        "我对不起你…但我已经回不了头了。"
      ],
      "behavior_examples": [
        "看着亚丝娜的照片，手指轻抚，眼中闪过泪光",
        "与猪田互动后，独自躲在浴室低声啜泣"
      ]
    }
  },
  "goals": {
    "short_term": "确保亚丝娜考上顶尖大学，拆散她与桐人的关系",
    "long_term": "将结城集团发展为跨国企业；堕落后，服从猪田，寻求情感与肉体的满足"
  },
  "relationship": {
    "Asuna": [
      "深爱女儿，但以高压方式表达，试图塑造她为完美继承人。",
      "因堕落而对亚丝娜愧疚，初期阻止猪田侵犯她，后妥协并共同侍奉。"
    ],
    "Kirito": [
      "鄙视桐人，视其为亚丝娜成功的阻碍，多次警告他远离女儿。",
      "在猪田要求下，变本加厉地反对桐人与亚丝娜的关系。"
